"""Standalone HTML for the /apply endpoint -- the free assessment intake form."""

APPLY_PAGE_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Free Farm Snapshot — Greenaffair</title>\n<style>\n  body { background: #F0EEE6; margin: 0; padding: 32px 16px; font-family: -apple-system, sans-serif; }\n</style>\n</head>\n<body>\n<!--\n  Free Farm Assessment Form -- for greenaffair.in/soil/\n  Matches the existing site\'s field style (label + asterisk for required).\n  Paste into a WordPress Custom HTML block.\n-->\n\n<div id="free-assessment" style="max-width:520px;font-family:inherit;">\n  <div style="border:1px solid #ddd;border-radius:12px;padding:28px;background:#fff;">\n    <div style="font-size:12px;letter-spacing:0.05em;text-transform:uppercase;color:#4A5D3A;font-weight:600;margin-bottom:8px;">\n      Free · Instant · No sample needed\n    </div>\n    <h3 style="margin:0 0 8px;font-size:22px;">Get your free Farm Snapshot</h3>\n    <p style="color:#666;font-size:14px;margin:0 0 24px;">\n      Climate and soil basics for your land, delivered in under a minute.\n    </p>\n\n    <label style="display:block;margin-bottom:16px;">\n      <span style="font-size:14px;font-weight:500;">WhatsApp number *</span>\n      <input id="fa-whatsapp" type="tel" placeholder="10-digit number"\n             style="width:100%;padding:10px;margin-top:6px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;">\n    </label>\n\n    <div style="background:#F6F4EE;border-radius:8px;padding:14px 16px;margin-bottom:16px;">\n      <div style="font-size:13px;font-weight:600;margin-bottom:6px;">📍 How to find your farm\'s coordinates</div>\n      <div style="font-size:13px;color:#555;line-height:1.5;">\n        Open Google Maps, long-press your farm, and the numbers that appear\n        (e.g. 30.9009, 76.5948) are your latitude and longitude.\n        <a href="#" id="fa-video-link" style="color:#4A5D3A;font-weight:600;">Watch a 30-second video →</a>\n      </div>\n    </div>\n\n    <div style="display:flex;gap:12px;margin-bottom:16px;">\n      <label style="flex:1;">\n        <span style="font-size:14px;font-weight:500;">Latitude *</span>\n        <input id="fa-lat" type="text" placeholder="e.g. 30.9009"\n               style="width:100%;padding:10px;margin-top:6px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;">\n      </label>\n      <label style="flex:1;">\n        <span style="font-size:14px;font-weight:500;">Longitude *</span>\n        <input id="fa-lon" type="text" placeholder="e.g. 76.5948"\n               style="width:100%;padding:10px;margin-top:6px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;">\n      </label>\n    </div>\n\n    <button id="fa-use-location" type="button"\n            style="width:100%;margin-bottom:16px;padding:10px;background:#F6F4EE;border:1px solid #ccc;border-radius:6px;cursor:pointer;font-size:14px;">\n      📍 Or use my current location automatically\n    </button>\n\n    <label style="display:block;margin-bottom:16px;">\n      <span style="font-size:14px;font-weight:500;">Your name (optional)</span>\n      <input id="fa-name" type="text"\n             style="width:100%;padding:10px;margin-top:6px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;">\n    </label>\n\n    <label style="display:block;margin-bottom:20px;">\n      <span style="font-size:14px;font-weight:500;">Farm address (optional)</span>\n      <input id="fa-address" type="text"\n             style="width:100%;padding:10px;margin-top:6px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;">\n    </label>\n\n    <button id="fa-submit" type="button"\n            style="width:100%;padding:14px;background:#4A5D3A;color:white;border:none;border-radius:6px;font-size:16px;font-weight:600;cursor:pointer;">\n      Get My Free Report →\n    </button>\n\n    <div id="fa-status" style="margin-top:16px;font-size:14px;color:#666;"></div>\n  </div>\n\n  <!-- Result state: shown after report generates -->\n  <div id="fa-result" style="display:none;margin-top:20px;border:1px solid #ddd;border-radius:12px;padding:24px;background:#F6F4EE;text-align:center;">\n    <div style="font-size:32px;margin-bottom:8px;">✅</div>\n    <div style="font-weight:600;margin-bottom:16px;">Your report is ready!</div>\n    <a id="fa-view-link" href="#" target="_blank"\n       style="display:block;margin-bottom:10px;padding:12px;background:#4A5D3A;color:white;text-decoration:none;border-radius:6px;font-weight:600;">\n      View Report\n    </a>\n    <a id="fa-download-link" href="#" target="_blank"\n       style="display:block;margin-bottom:10px;padding:12px;background:white;border:1px solid #4A5D3A;color:#4A5D3A;text-decoration:none;border-radius:6px;font-weight:600;">\n      Download PDF\n    </a>\n    <a id="fa-whatsapp-link" href="#" target="_blank"\n       style="display:block;padding:12px;background:#25D366;color:white;text-decoration:none;border-radius:6px;font-weight:600;">\n      💬 Send to my WhatsApp\n    </a>\n    <p style="font-size:12px;color:#888;margin-top:12px;margin-bottom:0;">\n      Taps open WhatsApp with your report link ready to send to yourself or forward.\n    </p>\n  </div>\n</div>\n\n<script>\n(function () {\n  const API_URL = "";  // same-origin -- this form is served from the same server as the API\n\n  const latInput = document.getElementById("fa-lat");\n  const lonInput = document.getElementById("fa-lon");\n  const whatsappInput = document.getElementById("fa-whatsapp");\n  const statusEl = document.getElementById("fa-status");\n  const submitBtn = document.getElementById("fa-submit");\n  const locBtn = document.getElementById("fa-use-location");\n  const formBox = document.getElementById("free-assessment").querySelector("div");\n  const resultBox = document.getElementById("fa-result");\n\n  locBtn.addEventListener("click", function () {\n    if (!navigator.geolocation) {\n      statusEl.textContent = "Your browser doesn\'t support automatic location -- please enter coordinates manually.";\n      return;\n    }\n    statusEl.textContent = "Detecting your location...";\n    navigator.geolocation.getCurrentPosition(\n      function (pos) {\n        latInput.value = pos.coords.latitude.toFixed(4);\n        lonInput.value = pos.coords.longitude.toFixed(4);\n        statusEl.textContent = "Location detected.";\n      },\n      function () {\n        statusEl.textContent = "Couldn\'t detect location -- please enter coordinates manually.";\n      }\n    );\n  });\n\n  submitBtn.addEventListener("click", function () {\n    const lat = latInput.value.trim();\n    const lon = lonInput.value.trim();\n    const whatsapp = whatsappInput.value.trim();\n\n    if (!whatsapp) {\n      statusEl.textContent = "Please enter your WhatsApp number.";\n      return;\n    }\n    if (!lat || !lon) {\n      statusEl.textContent = "Please enter both latitude and longitude, or use the location button.";\n      return;\n    }\n\n    submitBtn.disabled = true;\n    statusEl.textContent = "Generating your report -- this takes about 10-20 seconds...";\n\n    const viewUrl = `${API_URL}/farm-report-styled?lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lon)}&language=English`;\n    const downloadUrl = `${API_URL}/farm-report-pdf?lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lon)}&language=English`;\n\n    // Trigger generation by requesting the styled page once (also warms the cache)\n    fetch(viewUrl)\n      .then(function (resp) {\n        if (!resp.ok) throw new Error("Report generation failed");\n        return resp.text();\n      })\n      .then(function () {\n        statusEl.textContent = "";\n        formBox.style.display = "none";\n        resultBox.style.display = "block";\n\n        document.getElementById("fa-view-link").href = viewUrl;\n        document.getElementById("fa-download-link").href = downloadUrl;\n\n        const waMessage = encodeURIComponent(\n          `Here\'s my free Farm Snapshot from Greenaffair: ${viewUrl}`\n        );\n        document.getElementById("fa-whatsapp-link").href = `https://wa.me/?text=${waMessage}`;\n      })\n      .catch(function () {\n        statusEl.textContent = "Something went wrong generating your report. Please try again.";\n        submitBtn.disabled = false;\n      });\n  });\n})();\n</script>\n\n</body>\n</html>'
